import{_ as n,a8 as e,o as d,c as _,ah as s,K as a}from"./chunks/framework.CIrX4_tc.js";import"./chunks/theme.DhGbIGPm.js";const u=JSON.parse('{"title":"AI中转站-三层架构与模块职责","description":"","frontmatter":{"title":"AI中转站-三层架构与模块职责","created":"2026-10-23T00:00:00.000Z","tags":["AI中转站","API网关","架构"],"type":"概念解释","abstract":"从接入、核心业务和输出三层理解AI中转站的模块分工。","category":["🧩 AI框架与Agent","框架与中间件"],"related":["[[1.架构与中间件-MOC]]","[[AI中转站-模型路由与成本优化]]","[[AI中转站-计费一致性与监控指标]]"],"reference":["[[Resources/人工智能/技术篇-一个AI中转站是怎么搭起来的]]"],"source":"https://zhuanlan.zhihu.com/p/2051972594253960155"},"headers":[],"relativePath":"vault/Knowledge/AI/AI中转站-三层架构与模块职责.md","filePath":"vault/Knowledge/AI/AI中转站-三层架构与模块职责.md","lastUpdated":1792811397000}'),l={name:"vault/Knowledge/AI/AI中转站-三层架构与模块职责.md"};function i(p,t,c,A,I,h){const o=e("NolebaseGitContributors"),r=e("NolebaseGitChangelog");return d(),_("div",null,[t[0]||(t[0]=s('<h1 id="ai中转站-三层架构与模块职责" tabindex="-1">AI中转站-三层架构与模块职责 <a class="header-anchor" href="#ai中转站-三层架构与模块职责" aria-label="Permalink to “AI中转站-三层架构与模块职责”">​</a></h1><p>按 API茶馆这篇文章的划分，中转站把多家模型服务转换为统一入口，业务可以分为三层。</p><table tabindex="0"><thead><tr><th>层次</th><th>职责</th></tr></thead><tbody><tr><td>接入层</td><td>通过适配器转换供应商请求参数、协议与响应结构</td></tr><tr><td>核心层</td><td>处理用户、计费、模型路由、负载、缓存和监控</td></tr><tr><td>输出层</td><td>向调用方提供统一接口；文中以兼容 OpenAI 格式为例</td></tr></tbody></table><p>适配器处理双向转换：请求进入时转换为供应商格式，响应返回时转回统一格式。接口版本变化、视频时长与比例等专有参数，是持续维护的重点。</p><p>文章把实现进一步拆为五个模块：适配器、计费、路由、缓存、日志与监控。搭起可调用的入口后，仍需处理稳定性、成本与用户信任。</p><p>以上是原文架构概括，不是接口兼容性测试。原文提到 One API、New API、LiteLLM，但本笔记未验证其当前功能，也不把“更换地址和密钥即可无缝切换”视作所有模型的保证。</p>',6)),a(o),a(r)])}const g=n(l,[["render",i]]);export{u as __pageData,g as default};
